def block_offending_cidrs(bpf_map: LPMMapClient, cidrs: list[str], ttl_s: int = 300) -> list[str]:
    applied: list[str] = []
    try:
        for raw in cidrs:
            net = ipaddress.ip_network(raw, strict=False)
            if net.prefixlen < 16 or any(net.overlaps(a) for a in PROTECTED_ALLOWLIST):
                continue  # Guard against blocking broad /8s or internal VPCs
            for attempt in range(3):
                try:
                    bpf_map.upsert_cidr(str(net), ttl_s=ttl_s)
                    applied.append(str(net))
                    break
                except OSError:
                    if attempt == 2:
                        raise
                    time.sleep((0.05 * (2 ** attempt)) + random.uniform(0, 0.02))
        return applied
    except Exception as exc:
        for c in applied:
            bpf_map.delete_cidr(c)  # Atomic rollback of partial batch
        raise RuntimeError(f'LPM blocklist update rolled back: {exc}') from exc
